def to_model_cache(cache):
    """
    将内部 legacy tuple cache 转换为新版 Transformers/Qwen
    forward 所需的 DynamicCache。

    内部 KV patch / KV 拼接逻辑继续使用：
        ((K_layer0, V_layer0), (K_layer1, V_layer1), ...)

    传入模型前：
        legacy tuple -> DynamicCache
    """

    if cache is None:
        return None

    # 已经是新版 Cache 对象，例如 DynamicCache。
    if hasattr(cache, "get_seq_length"):
        return cache

    # Legacy tuple/list cache。
    if isinstance(cache, (tuple, list)):
        return DynamicCache.from_legacy_cache(cache)

    return cache


def model_forward_with_cache(model, **kwargs):
    """
    统一模型 forward wrapper。

    若 kwargs 中存在 legacy tuple past_key_values，
    则自动转换为 DynamicCache 后再调用模型。
    """

    if "past_key_values" in kwargs:
        kwargs["past_key_values"] = to_model_cache(
            kwargs["past_key_values"]
        )

    return model(**kwargs)


def normalize_text(text):
    if text is None:
        return ""

    text = str(text).lower()
    text = text.replace("_", " ")
    text = re.sub(r"[^a-z0-9\s]", " ", text)
    text = re.sub(r"\s+", " ", text)

    return text.strip()


def normalize_scores(values):
    values = np.asarray(values, dtype=np.float64)

    if len(values) == 0:
        return values

    low = values.min()
    high = values.max()

    if high - low < 1e-12:
        return np.zeros_like(values)

    return (values - low) / (high - low)


def safe_spearman(x, y):
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)

    valid = ~(np.isnan(x) | np.isnan(y))

    x = x[valid]
    y = y[valid]

    if len(x) < 2:
        return np.nan

    rank_x = pd.Series(x).rank(method="average").to_numpy()
    rank_y = pd.Series(y).rank(method="average").to_numpy()

    rank_x = rank_x - rank_x.mean()
    rank_y = rank_y - rank_y.mean()

    denominator = (
        np.linalg.norm(rank_x)
        * np.linalg.norm(rank_y)
    )

    if denominator < 1e-12:
        return np.nan

    return float(np.dot(rank_x, rank_y) / denominator)


# ============================================================
# 2. Prompt Span 定位
# ============================================================


def top_k_indices(scores, k):
    """
    返回 scores 中最大的 Top-K 元素的局部索引。

    参数：
        scores: 1D numpy array / list
        k: 选择数量

    返回：
        List[int]
    """

    scores = np.asarray(
        scores,
        dtype=np.float64,
    )

    if len(scores) == 0:
        return []

    k = min(
        int(k),
        len(scores),
    )

    if k <= 0:
        return []

    return np.argsort(scores)[::-1][:k].tolist()


def find_question_char_span(prompt):
    marker_q = "Question: "
    marker_a = "\nAnswer:"

    start = prompt.rfind(marker_q)

    if start < 0:
        raise RuntimeError("Cannot find Question marker.")

    start += len(marker_q)

    end = prompt.find(marker_a, start)

    if end < 0:
        raise RuntimeError("Cannot find Answer marker.")

    return start, end


def find_target_path_char_spans(prompt, hop_length):
    path_open_pattern = (
        r"<KG_PATH\s+id=P_TARGET_LONG\s+"
        r"block=TARGET_PATH[^>]*>"
    )

    open_match = re.search(
        path_open_pattern,
        prompt,
    )

    if open_match is None:
        raise RuntimeError(
            "Cannot find target KG_PATH opening tag."
        )

    path_start = open_match.start()

    close_tag = "</KG_PATH>"
    close_pos = prompt.find(
        close_tag,
        open_match.end(),
    )

    if close_pos < 0:
        raise RuntimeError(
            "Cannot find target KG_PATH closing tag."
        )

    path_end = close_pos + len(close_tag)

    hop_spans = []

    for hop_id in range(1, hop_length + 1):
        triple_open = rf"<TRIPLE\s+hop={hop_id}>"

        triple_match = re.search(
            triple_open,
            prompt[path_start:path_end],
        )

        if triple_match is None:
            raise RuntimeError(
                f"Cannot find Triple hop={hop_id}."
            )

        triple_start = path_start + triple_match.start()

        triple_close = "</TRIPLE>"
        triple_end_pos = prompt.find(
            triple_close,
            triple_start,
        )

        if triple_end_pos < 0:
            raise RuntimeError(
                f"Cannot close Triple hop={hop_id}."
            )

        triple_end = triple_end_pos + len(triple_close)

        hop_spans.append(
            (triple_start, triple_end)
        )

    return {
        "path_char_span": (
            path_start,
            path_end,
        ),
        "hop_char_spans": hop_spans,
    }


def find_slot_content_spans(prompt, hop_span):
    """
    用于给 token 赋类型：
        subject_entity
        relation
        object_entity
        structure
    """

    start, end = hop_span
    text = prompt[start:end]

    slots = {
        "subject_entity": (
            "<SUBJECT>",
            "</SUBJECT>",
        ),
        "relation": (
            "<RELATION>",
            "</RELATION>",
        ),
        "object_entity": (
            "<OBJECT>",
            "</OBJECT>",
        ),
    }

    output = {}

    for name, (open_tag, close_tag) in slots.items():
        open_pos = text.find(open_tag)

        if open_pos < 0:
            output[name] = None
            continue

        content_start = open_pos + len(open_tag)

        close_pos = text.find(
            close_tag,
            content_start,
        )

        if close_pos < 0:
            output[name] = None
            continue

        output[name] = (
            start + content_start,
            start + close_pos,
        )

    return output


# ============================================================
# 3. Tokenization 与类型分类
# ============================================================

def tokenize_with_offsets(tokenizer, prompt):
    encoded = tokenizer(
        prompt,
        return_tensors="pt",
        return_offsets_mapping=True,
        add_special_tokens=False,
    )

    return {
        "input_ids": encoded["input_ids"][0].cpu(),
        "offsets": encoded["offset_mapping"][0].tolist(),
    }


def char_span_to_token_positions(
    offsets,
    char_start,
    char_end,
):
    positions = []

    for token_index, (start, end) in enumerate(offsets):
        if start == end:
            continue

        if end > char_start and start < char_end:
            positions.append(token_index)

    if len(positions) == 0:
        raise RuntimeError(
            f"No token overlaps span [{char_start}, {char_end})."
        )

    return positions


def overlap_length(span_a, span_b):
    a0, a1 = span_a
    b0, b1 = span_b

    return max(0, min(a1, b1) - max(a0, b0))


def classify_token_type(token_span, slot_spans):
    priority = {
        "structure": 0,
        "subject_entity": 1,
        "relation": 2,
        "object_entity": 3,
    }

    selected_type = "structure"
    max_overlap = 0

    for hop_slots in slot_spans.values():
        for token_type, slot_span in hop_slots.items():
            if slot_span is None:
                continue

            overlap = overlap_length(
                token_span,
                slot_span,
            )

            if overlap > max_overlap:
                selected_type = token_type
                max_overlap = overlap

            elif (
                overlap == max_overlap
                and overlap > 0
                and priority[token_type]
                > priority[selected_type]
            ):
                selected_type = token_type

    return selected_type


def extract_prompt_spans(tokenizer, prompt, hop_length):
    tokenized = tokenize_with_offsets(tokenizer, prompt)

    input_ids = tokenized["input_ids"]
    offsets = tokenized["offsets"]

    char_info = find_target_path_char_spans(
        prompt,
        hop_length,
    )

    hop_positions = []

    for hop_start, hop_end in char_info["hop_char_spans"]:
        positions = char_span_to_token_positions(
            offsets,
            hop_start,
            hop_end,
        )

        hop_positions.append(positions)

    evidence_positions = sorted(
        {
            position
            for positions in hop_positions
            for position in positions
        }
    )

    if len(evidence_positions) != sum(
        len(positions)
        for positions in hop_positions
    ):
        raise RuntimeError(
            "Triple spans overlap unexpectedly."
        )

    full_path_positions = char_span_to_token_positions(
        offsets,
        char_info["path_char_span"][0],
        char_info["path_char_span"][1],
    )

    full_path_span = (
        full_path_positions[0],
        full_path_positions[-1] + 1,
    )

    question_start, question_end = find_question_char_span(prompt)

    question_positions = char_span_to_token_positions(
        offsets,
        question_start,
        question_end,
    )

    global_to_hop = {}

    for hop_index, positions in enumerate(
        hop_positions,
        start=1,
    ):
        for position in positions:
            global_to_hop[position] = hop_index

    slot_spans = {}

    for hop_index, char_span in enumerate(
        char_info["hop_char_spans"],
        start=1,
    ):
        slot_spans[hop_index] = find_slot_content_spans(
            prompt,
            char_span,
        )

    token_types = []

    for position in evidence_positions:
        token_types.append(
            classify_token_type(
                offsets[position],
                slot_spans,
            )
        )

    return {
        "input_ids": input_ids,
        "offsets": offsets,
        "evidence_positions": evidence_positions,
        "hop_positions": hop_positions,
        "question_positions": question_positions,
        "full_path_span": full_path_span,
        "global_to_hop": global_to_hop,
        "token_types": token_types,
    }


