def plot_top_token_heatmap(
    token_df,
    output_dir,
    max_samples=12,
    top_k=20,
):
    """
    为 KL reduction 最大的若干样本绘制：

        Prompt token position × causal repair effect

    每行一个 sample；
    每列是 evidence path 内 token position；
    颜色为 step_kl_reduction。

    用于观察高影响 token 是否集中在类似位置。
    """

    attributed_df = token_df[
        token_df["was_attributed"] == 1
    ].copy()

    if len(attributed_df) == 0:
        return

    sample_scores = (
        attributed_df.groupby("sample_id")[
            "reuse_step_kl"
        ]
        .first()
        .sort_values(ascending=False)
    )

    selected_samples = sample_scores.head(
        max_samples
    ).index.tolist()

    subset = attributed_df[
        attributed_df["sample_id"].isin(
            selected_samples
        )
    ].copy()

    pivot = subset.pivot(
        index="sample_id",
        columns="path_local_index",
        values="step_kl_reduction",
    )

    pivot = pivot.reindex(
        selected_samples
    )

    if pivot.shape[1] > top_k:
        # 选择全局平均 KL reduction 较高的位置；
        # 使热图更适合论文展示。
        important_positions = (
            subset.groupby("path_local_index")[
                "step_kl_reduction"
            ]
            .mean()
            .sort_values(ascending=False)
            .head(top_k)
            .index
            .tolist()
        )

        important_positions = sorted(
            important_positions
        )

        pivot = pivot.reindex(
            columns=important_positions
        )

    fig_width = max(
        10,
        min(
            22,
            0.55 * pivot.shape[1] + 5,
        ),
    )

    fig_height = max(
        5,
        min(
            12,
            0.42 * pivot.shape[0] + 3,
        ),
    )

    fig, ax = plt.subplots(
        figsize=(fig_width, fig_height),
    )

    maximum = np.nanmax(
        np.abs(pivot.to_numpy())
    )

    if not np.isfinite(maximum) or maximum < 1e-8:
        maximum = 1.0

    sns.heatmap(
        pivot,
        cmap="coolwarm",
        center=0,
        vmin=-maximum,
        vmax=maximum,
        linewidths=0.25,
        linecolor="white",
        cbar_kws={
            "label": (
                "Step-KL Reduction after "
                "Single-Token KV Patch"
            )
        },
        ax=ax,
    )

    ax.set_title(
        "Decode-Step Causal Repair Effect Across Prompt Token Positions",
        pad=12,
        fontweight="bold",
    )

    ax.set_xlabel(
        "Target KG Evidence Token Position"
    )

    ax.set_ylabel(
        "High-KL Sample ID"
    )

    save_figure(
        fig,
        output_dir,
        "05_decode_step_token_effect_heatmap",
    )


