# 12. JSONL Loader
# ============================================================

def load_jsonl(path, max_samples):
    records = []

    with open(
        path,
        "r",
        encoding="utf-8",
    ) as file:
        for line in file:
            line = line.strip()

            if not line:
                continue

            records.append(json.loads(line))

            if len(records) >= max_samples:
                break

    return records


