# 13. Main
# ============================================================

def main():
    parser = argparse.ArgumentParser(
        description=(
            "Decode-step prompt token causal attribution "
            "for KV cache reuse."
        )
    )

    parser.add_argument(
        "--benchmark_jsonl",
        type=str,
        required=True,
    )

    parser.add_argument(
        "--output_dir",
        type=str,
        required=True,
    )

    parser.add_argument(
        "--primary_model",
        type=str,
        default="Qwen/Qwen2.5-3B-Instruct",
    )

    parser.add_argument(
        "--device",
        type=str,
        default=(
            "cuda"
            if torch.cuda.is_available()
            else "cpu"
        ),
    )

    parser.add_argument(
        "--dtype",
        type=str,
        default="bfloat16",
        choices=[
            "bfloat16",
            "float16",
            "float32",
        ],
    )

    parser.add_argument(
        "--max_samples",
        type=int,
        default=10,
        help=(
            "Single-token causal attribution is expensive. "
            "Start with 3-10 samples."
        ),
    )

    parser.add_argument(
        "--target_generation_step",
        type=int,
        default=8,
        help=(
            "Decode step whose KL error is analyzed."
        ),
    )

    parser.add_argument(
        "--max_new_tokens",
        type=int,
        default=12,
        help=(
            "Maximum Full-Recompute reference generation length."
        ),
    )

    parser.add_argument(
        "--max_attribution_tokens",
        type=int,
        default=None,
        help=(
            "Optional cap on attributed prompt evidence tokens. "
            "When set, only tokens with the largest raw K/V deviation "
            "are individually patched. Default: all evidence tokens."
        ),
    )

    parser.add_argument(
        "--heatmap_samples",
        type=int,
        default=12,
    )

    parser.add_argument(
        "--heatmap_positions",
        type=int,
        default=30,
    )

    args = parser.parse_args()

    benchmark_path = Path(
        args.benchmark_jsonl
    )

    output_dir = Path(
        args.output_dir
    )

    figure_dir = output_dir / "figures"

    output_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    figure_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    if not benchmark_path.exists():
        raise FileNotFoundError(
            f"Benchmark not found:\n{benchmark_path}"
        )

    if (
        args.device.startswith("cuda")
        and not torch.cuda.is_available()
    ):
        raise RuntimeError(
            "CUDA requested but unavailable."
        )

    if args.target_generation_step < 1:
        raise ValueError(
            "target_generation_step must be >= 1."
        )

    dtype = parse_dtype(args.dtype)

    setup_paper_style()

    print("=" * 120)
    print(
        "Decode-Step Prompt Token Causal Attribution"
    )
    print("=" * 120)
    print(f"Benchmark: {benchmark_path}")
    print(f"Output: {output_dir}")
    print(f"Primary model: {args.primary_model}")
    print(
        f"Target decode step: "
        f"{args.target_generation_step}"
    )
    print(
        f"Max attribution tokens: "
        f"{args.max_attribution_tokens}"
    )
    print(f"Max samples: {args.max_samples}")
    print("=" * 120)

    records = load_jsonl(
        benchmark_path,
        args.max_samples,
    )

    if len(records) == 0:
        raise RuntimeError(
            "No benchmark records loaded."
        )

    print(
        f"Loaded samples: {len(records)}"
    )

    print("\nLoading primary model...")

    tokenizer, model = load_model(
        model_name=args.primary_model,
        device=args.device,
        dtype=dtype,
    )

    model_device = get_model_device(model)

    token_frames = []
    sample_frames = []
    metadata_rows = []

    successful_samples = 0

    for sample_index, record in enumerate(
        records,
        start=1,
    ):
        sample_id = record.get(
            "sample_id",
            f"sample_{sample_index:05d}",
        )

        print("\n" + "#" * 120)
        print(
            f"[{sample_index}/{len(records)}] "
            f"{sample_id}"
        )
        print("#" * 120)

        try:
            (
                token_df,
                sample_df,
                metadata,
            ) = run_one_sample(
                record=record,
                large_tokenizer=tokenizer,
                large_model=model,
                large_device=model_device,
                args=args,
            )

            token_frames.append(token_df)
            sample_frames.append(sample_df)
            metadata_rows.append(metadata)

            successful_samples += 1

            print(
                f"  Target Step-{args.target_generation_step} "
                f"reference token: "
                f"{metadata['reference_token_text']!r}"
            )

            print(
                f"  Full Reuse KL: "
                f"{metadata['reuse_step_kl']:.6f}"
            )

            print(
                f"  Evidence tokens: "
                f"{metadata['evidence_token_count']}"
            )

            print(
                f"  Attributed tokens: "
                f"{metadata['attributed_token_count']}"
            )

        except Exception as exc:
            print(
                f"[Warning] Failed sample "
                f"{sample_id}: {exc}"
            )

        gc.collect()

        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    if len(token_frames) == 0:
        raise RuntimeError(
            "No samples completed successfully."
        )

    token_df = pd.concat(
        token_frames,
        ignore_index=True,
    )

    sample_df = pd.concat(
        sample_frames,
        ignore_index=True,
    )

    metadata_df = pd.DataFrame(
        metadata_rows
    )

    # ========================================================
    # 聚合分析
    # ========================================================

    hop_df = aggregate_by_hop(
        token_df
    )

    token_type_df = aggregate_by_token_type(
        token_df
    )

    position_df = aggregate_by_relative_position(
        token_df
    )

    correlation_per_sample_df, correlation_summary_df = (
        aggregate_attention_deviation_alignment(
            token_df
        )
    )

    attributed_df = token_df[
        token_df["was_attributed"] == 1
    ].copy()

    top_tokens_df = (
        attributed_df.sort_values(
            [
                "sample_id",
                "step_kl_reduction",
            ],
            ascending=[
                True,
                False,
            ],
        )
        .groupby(
            "sample_id",
            group_keys=False,
        )
        .head(20)
        .reset_index(drop=True)
    )

    global_top_tokens_df = (
        attributed_df.sort_values(
            "step_kl_reduction",
            ascending=False,
        )
        .head(200)
        .reset_index(drop=True)
    )

    # ========================================================
    # 保存结果
    # ========================================================

    output_files = {
        "per_prompt_token_decode_attribution.csv": token_df,
        "per_sample_decode_summary.csv": sample_df,
        "hop_decode_importance_summary.csv": hop_df,
        "token_type_decode_importance_summary.csv": (
            token_type_df
        ),
        "position_decode_importance_summary.csv": (
            position_df
        ),
        "per_sample_deviation_effect_correlation.csv": (
            correlation_per_sample_df
        ),
        "deviation_effect_correlation_summary.csv": (
            correlation_summary_df
        ),
        "top_prompt_tokens_per_sample.csv": (
            top_tokens_df
        ),
        "top_prompt_tokens_global.csv": (
            global_top_tokens_df
        ),
        "sample_metadata.csv": metadata_df,
    }

    for filename, dataframe in output_files.items():
        path = output_dir / filename

        dataframe.to_csv(
            path,
            index=False,
            encoding="utf-8",
        )

        print(f"[Saved] {path}")

    metadata_json = {
        "benchmark_jsonl": str(
            benchmark_path.resolve()
        ),
        "output_dir": str(
            output_dir.resolve()
        ),
        "primary_model": args.primary_model,
        "target_generation_step": (
            args.target_generation_step
        ),
        "max_new_tokens": args.max_new_tokens,
        "max_samples_requested": args.max_samples,
        "successful_samples": successful_samples,
        "max_attribution_tokens": (
            args.max_attribution_tokens
        ),
        "causal_metric": {
            "step_kl_reduction": (
                "KL(full || reuse) - KL(full || "
                "single-token-target-KV-patch)"
            ),
            "reference_logprob_gain": (
                "logP_patch(reference token) - "
                "logP_reuse(reference token)"
            ),
            "reference_margin_gain": (
                "margin_patch(reference token) - "
                "margin_reuse(reference token)"
            ),
        },
        "interpretation": (
            "A positive step_kl_reduction indicates that "
            "patching the token's Target K/V decreases KL at "
            "the target decode step. Such tokens are the most "
            "causally implicated prompt evidence tokens under "
            "this single-token Oracle KV patch intervention."
        ),
        "limitation": (
            "This is a hybrid KV cache intervention. "
            "It does not perform exact causal suffix recomputation "
            "from the patched token, so effects reflect the "
            "token-level patch mechanism used in CacheClip analysis."
        ),
    }

    metadata_path = (
        output_dir
        / "analysis_metadata.json"
    )

    metadata_path.write_text(
        json.dumps(
            metadata_json,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    config_path = output_dir / "run_config.json"

    config_path.write_text(
        json.dumps(
            vars(args),
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    print(f"[Saved] {metadata_path}")
    print(f"[Saved] {config_path}")

    # ========================================================
    # 可视化
    # ========================================================

    plot_token_deviation_vs_effect(
        token_df,
        figure_dir,
    )

    plot_hop_effect(
        hop_df,
        figure_dir,
    )

    plot_token_type_effect(
        token_type_df,
        figure_dir,
    )

    plot_relative_position_effect(
        position_df,
        figure_dir,
    )

    plot_top_token_heatmap(
        token_df,
        figure_dir,
        max_samples=args.heatmap_samples,
        top_k=args.heatmap_positions,
    )

    # ========================================================
    # 控制台结果
    # ========================================================

    print("\n" + "=" * 120)
    print(
        "Top Prompt Tokens by Decode-Step KL Reduction"
    )
    print("=" * 120)

    display_columns = [
        "sample_id",
        "target_generation_step",
        "reference_token_text",
        "path_local_index",
        "global_prompt_position",
        "token_label",
        "hop_index",
        "token_type",
        "key_relative_deviation_mean",
        "value_relative_deviation_mean",
        "raw_kv_deviation_score",
        "reuse_step_kl",
        "patched_step_kl",
        "step_kl_reduction",
        "reference_logprob_gain",
        "reference_margin_gain",
        "top1_match_improvement",
    ]

    display_columns = [
        column
        for column in display_columns
        if column in global_top_tokens_df.columns
    ]

    print(
        global_top_tokens_df[
            display_columns
        ].head(50).to_string(
            index=False,
            max_colwidth=35,
            float_format=lambda value: (
                f"{value:.7f}"
            ),
        )
    )

    print("\n" + "=" * 120)
    print("Hop-Level Decode Importance")
    print("=" * 120)

    print(
        hop_df.to_string(
            index=False,
            float_format=lambda value: (
                f"{value:.7f}"
            ),
        )
    )

    print("\n" + "=" * 120)
    print("Token-Type Decode Importance")
    print("=" * 120)

    print(
        token_type_df.to_string(
            index=False,
            float_format=lambda value: (
                f"{value:.7f}"
            ),
        )
    )

    print("\n" + "=" * 120)
    print("Raw KV Deviation vs Decode Repair Correlation")
    print("=" * 120)

    print(
        correlation_summary_df.to_string(
            index=False,
            float_format=lambda value: (
                f"{value:.7f}"
            ),
        )
    )

    print("\n" + "=" * 120)
    print(
        f"Completed: {successful_samples}/"
        f"{len(records)} samples"
    )
    print(
        f"Results saved to:\n{output_dir.resolve()}"
    )
    print("=" * 120)


if __name__ == "__main__":
    main()
   

